int main(int argc,char**argv){QCoreApplication app(argc,argv);bool ok=true;auto a=item(1,"First"),b=item(2,"Second");b.item.sourceBuildId=44;b.sourceBuildReference="MOC-1";b.sourceBuildName="Source Build";const auto rows=CollectionExportService::createRows({a,b});ok&=check(rows.size()==2&&rows[0].source=="Catalog / Existing Collection"&&rows[1].source=="Build: Source Build (MOC-1)","stable source Build semantics");ok&=check(rows[0].allowPartsSource&&!rows[1].allowPartsSource,"stored parts-source preference");auto c=CollectionExportService::defaultConfiguration();auto p=CollectionExportService::project(rows,c);ok&=check(p.rows.size()==2&&p.headers.first()=="Type"&&p.headers.contains("Consider for What Can I Build"),"defaults and physical-copy granularity");c.enabledFields.insert("notes");c.fieldOrder.prepend("notes");p=CollectionExportService::project(rows,c);const auto csv=CollectionCsvWriter::generate(p);ok&=check(csv.success&&csv.csv.startsWith(QChar(0xFEFF))&&csv.csv.contains("\"Comma, quote \"\" and\nUnicode: café\""),"notes CSV quoting and Unicode");QList<CollectionExportRow> many;for(int i=0;i<300;++i)many<<rows.first();ok&=check(CollectionExportService::project(many,c,250).rows.size()==250&&CollectionExportService::project(many,c).rows.size()==300,"bounded preview preserves complete export");auto normalized=CollectionExportService::normalizeConfiguration({"state","stale","type"},{"state","stale"});ok&=check(normalized.fieldOrder.first()=="state"&&!normalized.fieldOrder.contains("stale")&&normalized.enabledFields==QSet<QString>{"state"},"stale settings ignored");RemoteReadDto::CollectionExportRow remote;remote.collectionItemId=9;remote.type="MOC";remote.reference="MOC-9";remote.name="Remote";remote.source="Build: Remote";const auto rr=CollectionExportService::createRemoteRows({remote});ok&=check(rr.size()==1&&rr.first().collectionItemId==9&&rr.first().source=="Build: Remote","Remote adapter");return ok?0:1;}
